  tenant: { name: 'OWASP: Multi Tenant Security Cheat Sheet', url: 'https://cheatsheetseries.owasp.org/cheatsheets/Multi_Tenant_Security_Cheat_Sheet.html' },
  logging: { name: 'OWASP: Logging Cheat Sheet', url: 'https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html' },
